inline constexpr std::string_view project_explorer_html=R"HTML(<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>SPARK · Projects</title>
<style>
:root{color-scheme:dark;--bg:#10151d;--panel:#171e29;--line:#2b3544;--text:#e5ecf5;--muted:#a2b1c4;--accent:#89dbbd}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font:15px/1.6 system-ui,sans-serif}a{color:var(--accent)}button,input,textarea{font:inherit}button,a,input{touch-action:manipulation}:focus-visible{outline:2px solid var(--accent);outline-offset:3px}button,.button{border:1px solid var(--line);border-radius:7px;padding:8px 13px;background:#202b38;color:var(--text);cursor:pointer;text-decoration:none}button:hover,.button:hover{background:#2e3d4e}button:disabled{opacity:.5;cursor:wait}.primary{background:var(--accent);color:var(--bg)}.danger,.error{color:#ffafb5}header{display:flex;justify-content:space-between;gap:16px;align-items:center;padding:22px 28px;border-bottom:1px solid var(--line)}header strong{letter-spacing:.16em;font-size:21px}header nav,.actions{display:flex;gap:12px;flex-wrap:wrap}main{max-width:1200px;margin:auto;padding:32px 24px}h1{margin:0;font-size:32px}h2{margin:0 0 12px;font-size:23px;overflow-wrap:anywhere}.muted{color:var(--muted)}.toolbar{display:flex;gap:12px;flex-wrap:wrap;margin:24px 0}input,textarea{background:var(--bg);color:var(--text);border:1px solid var(--line);border-radius:7px;padding:10px;width:100%}textarea{resize:vertical;min-height:130px}.toolbar input{margin-left:auto;width:300px;max-width:100%}#status{min-height:24px;overflow-wrap:anywhere}.grid{display:grid;grid-template-columns:minmax(220px,1fr) minmax(0,2fr);gap:24px}.panel{background:var(--panel);border:1px solid var(--line);border-radius:12px;padding:24px;min-width:0}#list{display:flex;flex-direction:column;gap:8px;max-height:65vh;overflow:auto}#list button{text-align:left;overflow-wrap:anywhere}#list button[aria-current=true]{background:#233b39;border-color:var(--accent)}#description{white-space:pre-wrap;overflow-wrap:anywhere}dl{display:grid;grid-template-columns:100px minmax(0,1fr);gap:12px}dt{color:var(--muted)}dd{margin:0;overflow-wrap:anywhere}.actions{margin-top:24px}#more{margin-top:16px}dialog{background:var(--panel);color:var(--text);border:1px solid var(--line);border-radius:12px;width:min(600px,94vw);max-height:90vh;padding:24px}dialog::backdrop{background:#05090dcc}label{display:block;margin:16px 0 5px}.radio{display:flex;align-items:flex-start;gap:10px}.radio input{width:auto;margin-top:7px}#directory-note,#delete-note{overflow-wrap:anywhere}dialog .actions{justify-content:flex-end}[hidden]{display:none!important}@media(max-width:680px){header{padding:16px;align-items:flex-start;flex-wrap:wrap}main{padding:24px 16px}.grid{grid-template-columns:1fr}.panel{padding:18px}#list{max-height:230px}.toolbar input{margin-left:0;width:100%}dl{grid-template-columns:1fr;gap:4px}dd{margin-bottom:10px}}

#boards{margin-top:24px}.board-toolbar{display:flex;gap:10px;flex-wrap:wrap;align-items:center}.board-toolbar select,dialog select{font:inherit;background:var(--bg);color:var(--text);border:1px solid var(--line);border-radius:7px;padding:10px;max-width:100%}#board-columns{display:flex;gap:16px;overflow-x:auto;align-items:flex-start;padding:12px 0}.kanban-column{flex:0 0 280px;min-width:0;background:var(--bg);padding:16px;border:1px solid var(--line);border-radius:10px}.kanban-column h3,.task-card h4{margin:0;overflow-wrap:anywhere}.kanban-column .actions{margin:12px 0}.task-card{background:var(--panel);border:1px solid var(--line);padding:14px;border-radius:8px;margin:12px 0}.task-card p{white-space:pre-wrap;overflow-wrap:anywhere}.kanban-column button{font-size:12px;padding:6px 9px}#board-status{min-height:24px}.board-toolbar select{min-width:180px}#board-form label{display:block}
#review-dialog{width:min(1100px,96vw)}.transfer-entry{padding:16px 0;border-top:1px solid var(--line)}.transfer-entry pre{white-space:pre-wrap;overflow-wrap:anywhere}.merge-sources{display:grid;grid-template-columns:1fr 1fr;gap:16px}.merge-editor textarea{min-height:240px;font:14px monospace}.merged-result{min-height:350px!important}@media(max-width:680px){.merge-sources{grid-template-columns:1fr}}</style></head><body>
<header><strong>SPARK</strong><nav aria-label="Main"><a href="/files/explorer">Files</a><a href="/api/docs">API reference</a></nav></header>
<main><h1>Projects</h1><p class="muted">Your ongoing work, files and repositories in one place.</p>
<div class="toolbar"><button id="create" data-spark-permission="projects.write files.write" class="primary">New project</button><button id="import-project" data-spark-permission="projects.read projects.write boards.read boards.write files.read files.write">Import project ZIP</button><button id="refresh">Refresh</button><input id="search" type="search" placeholder="Filter loaded projects" aria-label="Filter loaded projects"></div>
<p id="transfer-status" role="status" aria-live="polite"></p><a id="transfer-download" hidden></a><p id="status" role="status" aria-live="polite">Loading projects…</p>
<div class="grid"><section class="panel" aria-label="Projects"><div id="list"></div><p id="empty" class="muted" hidden>No projects yet. Create one to get started.</p><p id="count" class="muted"></p><button id="more" hidden>Load more</button></section>
<section class="panel" aria-label="Project details"><p id="prompt" class="muted">Select a project to view its details.</p><div id="details" hidden><h2 id="name"></h2><p id="description"></p><dl><dt>Parent</dt><dd id="parent"></dd><dt>Drive</dt><dd id="project-drive-status"></dd><dt>Directory</dt><dd><a id="directory"></a></dd><dt>GitHub</dt><dd id="github"></dd><dt>Created</dt><dd id="created"></dd><dt>Updated</dt><dd id="updated"></dd><dt>Project ID</dt><dd id="project-id"></dd></dl><h3>Subprojects</h3><div id="children" class="actions"></div><div class="actions"><button id="add-child" data-spark-permission="projects.write files.write">New subproject</button><a id="files" class="button">Open files</a><button id="export-project" data-spark-permission="projects.read boards.read files.read files.write">Export project ZIP</button><button id="edit" data-spark-permission="projects.write">Edit project</button><button id="delete" data-spark-permission="projects.write boards.write" class="danger">Delete project</button></div></div></section></div>
<section id="boards" class="panel" hidden><h2>Boards</h2><div class="board-toolbar"><select id="board-picker" aria-label="Board"></select><button id="board-new" data-spark-permission="boards.write" class="primary">New board</button><button id="board-rename" data-spark-permission="boards.write">Rename board</button><button id="board-delete" data-spark-permission="boards.write" class="danger">Delete board</button><button id="column-new" data-spark-permission="boards.write">New column</button><button id="board-refresh">Refresh boards</button></div><p id="board-status" role="status"></p><div id="board-columns"></div></section>
<noscript>JavaScript is required to manage projects.</noscript></main>
<dialog id="editor"><form id="form"><h2 id="form-title">New project</h2><label for="project-name">Name</label><input id="project-name" required autocomplete="off"><label for="project-description">Description</label><textarea id="project-description"></textarea><label for="project-github">GitHub repository (optional)</label><input id="project-github" type="url" placeholder="https://github.com/owner/repository"><label for="project-drive">Storage drive</label><select id="project-drive" style="padding:10px;background:var(--bg);color:var(--text);width:100%"></select><p id="directory-note" class="muted"></p><p id="form-error" class="error" role="alert"></p><div class="actions"><button id="cancel" type="button">Cancel</button><button id="save" class="primary" type="submit">Save project</button></div></form></dialog>
<dialog id="deletion"><form id="delete-form"><h2 id="delete-title">Delete project?</h2><p id="delete-note"></p><label class="radio"><input type="radio" name="retention" value="keep" checked>Keep the directory and all files</label><label class="radio"><input type="radio" name="retention" value="destroy">Permanently delete the directory and all nested files</label><p id="delete-error" class="error" role="alert"></p><div class="actions"><button id="delete-cancel" type="button">Cancel</button><button id="delete-confirm" type="submit" class="danger">Delete project</button></div></form></dialog>
<dialog id="board-editor"><form id="board-form"><h2 id="board-form-title"></h2><p id="board-form-note"></p><div id="board-name-field"><label for="board-name">Name</label><input id="board-name" autocomplete="off" required></div><div id="board-description-field"><label for="board-description">Description</label><textarea id="board-description"></textarea></div><div id="board-severity-field"><label for="board-severity">Severity</label><select id="board-severity"><option>Very Low</option><option>Low</option><option selected>Normal</option><option>High</option><option>Very High</option><option>Urgent</option></select></div><div id="board-destination-field"><label for="board-destination">Column</label><select id="board-destination"></select></div><p id="board-error" class="error" role="alert"></p><div class="actions"><button id="board-cancel" type="button">Cancel</button><button id="board-save" type="submit" class="primary">Save</button></div></form></dialog>
<dialog id="import-dialog"><form id="import-form"><h2>Import project ZIP</h2><p>Upload a SPARK project export. Review changes before applying them. The uploaded ZIP is retained in Files → /project-imports.</p><label for="import-upload">Project ZIP</label><input id="import-upload" type="file" accept=".zip,application/zip" required><label for="import-drive">Target drive</label><select id="import-drive"></select><label for="import-target">Target project</label><select id="import-target"></select><p id="import-error" class="error" role="alert"></p><div class="actions"><button id="import-cancel" type="button">Cancel</button><button id="import-prepare" type="submit">Upload and review</button></div></form></dialog>
<dialog id="review-dialog"><h2>Review project import</h2><p id="review-summary"></p><p>Only UTF-8 text file conflicts up to 1 MiB support merging. Use the source panes to edit the final result. Binary files can be kept or replaced.</p><div id="review-entries"></div><p id="review-error" class="error" role="alert"></p><div class="actions"><button id="review-cancel">Discard import</button><button id="review-apply" class="primary">Apply reviewed changes</button></div></dialog>
<script src="/auth/client.js"></script>
<script>
'use strict';
const $=id=>document.getElementById(id);let projects=[],selected=null,editing=null,creatingParent=null,deleting=null,more=false,busy=false,loading=false,revision=0,detailRevision=0;
function message(text,error=false){$('status').textContent=text;$('status').classList.toggle('error',error);}
async function api(path,options={}){const r=await fetch(path,{cache:'no-store',...options});if(!r.ok){let code='HTTP '+r.status;try{code=(await r.json()).error||code;}catch{}throw new Error(code.replaceAll('_',' '));}return r.status===204?null:r.json();}
function lock(){for(const id of ['create','refresh','more','edit','delete','add-child'])$(id).disabled=busy||loading;for(const id of ['save','cancel','delete-confirm','delete-cancel'])$(id).disabled=busy;for(const field of document.querySelectorAll('dialog input,dialog textarea,dialog select'))field.disabled=busy;for(const control of document.querySelectorAll('#boards button,#boards select'))control.disabled=busy||loading||boardLoading;for(const id of ['board-save','board-cancel'])$(id).disabled=busy;}
function render(){const query=$('search').value.toLowerCase();$('list').replaceChildren();let visible=0;for(const p of projects){if(!(p.name+' '+p.description).toLowerCase().includes(query))continue;visible++;const b=document.createElement('button');b.textContent=p.name;if(p.parent_id){const hint=document.createElement('small');hint.textContent=p.directory;hint.style.display='block';hint.className='muted';b.append(hint);}b.setAttribute('aria-current',String(selected?.id===p.id));b.onclick=()=>{if(!busy)location.hash=p.id;};$('list').append(b);}$('empty').hidden=visible>0;$('empty').textContent=query?'No matching loaded projects.':loading?'Loading…':'No projects yet. Create one to get started.';$('count').textContent=projects.length+' projects loaded';$('more').hidden=!more;lock();}
function show(p){selected=p;$('boards').hidden=!p;if(p)loadBoards(p.id);else {++boardRevision;boardLoading=false;}$('details').hidden=!p;$('prompt').hidden=!!p;if(p){$('parent').replaceChildren();if(p.parent_id){const a=document.createElement('a');a.href='#'+p.parent_id;a.textContent=projects.find(item=>item.id===p.parent_id)?.name||'Open parent project';$('parent').append(a);}else $('parent').textContent='Top-level project';$('children').replaceChildren();for(const child of p.subprojects||[]){const a=document.createElement('a');a.className='button';a.href='#'+(typeof child==='string'?child:child.id);a.textContent=typeof child==='string'?child:child.name;$('children').append(a);}if(!p.subprojects?.length)$('children').textContent='No subprojects yet.';$('name').textContent=p.name;$('description').textContent=p.description||'No description.';$('project-drive-status').textContent=p.drive_letter+': '+(p.drive_online?'Online':'Offline — files unavailable');$('directory').textContent=p.drive_letter+':'+p.directory;const url='/files/explorer?drive='+encodeURIComponent(p.drive_letter)+'#'+encodeURIComponent(p.directory);$('directory').href=url;$('files').href=url;$('github').replaceChildren();if(p.github_url && /^https:\/\/github\.com\/[A-Za-z0-9_-]+\/[A-Za-z0-9_.-]+\/?$/.test(p.github_url)){const a=document.createElement('a');a.textContent=p.github_url;a.href=p.github_url;a.target='_blank';a.rel='noopener noreferrer';$('github').append(a);}else $('github').textContent='Not linked';$('created').textContent=new Date(p.created_at).toLocaleString();$('updated').textContent=new Date(p.updated_at).toLocaleString();$('project-id').textContent=p.id;}render();}
async function select(){const token=++detailRevision;const id=location.hash.slice(1);if(!id){show(null);return;}if(!/^[0-9a-f-]{36}$/.test(id)){show(null);message('Invalid project link.',true);return;}try{const p=await api('/projects/'+id+'?depth=deep');if(token===detailRevision)show(p);}catch(e){if(token===detailRevision){show(null);message('Could not load project: '+e.message+'. Use Refresh to retry.',true);}}}
async function load(append=false){if(loading||busy)return;const token=++revision;loading=true;lock();message('Loading projects…');try{const page=await api('/projects?limit=100&offset='+(append?projects.length:0));if(token!==revision)return;projects=append?projects.concat(page.projects):page.projects;more=page.has_more;message('');await select();}catch(e){message('Could not load projects: '+e.message+'. Use Refresh to retry.',true);}finally{loading=false;render();}}
function directoryNote(){ $('directory-note').textContent=editing?'Storage stays '+editing.drive_letter+':'+editing.directory+' when renamed. Drive cannot be changed here.':'Directory: '+$('project-drive').value+':'+(creatingParent?creatingParent.directory:'/projects')+'/'+$('project-name').value+'. Any existing files there will be kept.';}
async function openEditor(p,parent=null){if(busy||loading)return;editing=p;creatingParent=parent;$('form-title').textContent=p?'Edit project':parent?'New subproject of '+parent.name:'New project';$('project-name').value=p?.name||'';$('project-description').value=p?.description||'';$('project-github').value=p?.github_url||'';$('form-error').textContent='';try{const drives=(await api('/files/drives')).drives;$('project-drive').replaceChildren();const fixed=p?.drive_letter||parent?.drive_letter;for(const d of drives)if(!fixed||d.letter===fixed){const option=new Option(d.letter+': '+(d.persistent?'Server storage':d.path)+(d.online?'':' (offline)'),d.letter);option.disabled=!d.online&&!fixed;$('project-drive').add(option);}if(fixed)$('project-drive').value=fixed;else $('project-drive').value=drives.find(d=>d.persistent)?.letter||'';}catch(error){message(error.message,true);return;}directoryNote();$('editor').showModal();$('project-name').focus();}
$('form').onsubmit=async e=>{e.preventDefault();if(busy)return;const packet={name:$('project-name').value,description:$('project-description').value,github_url:$('project-github').value.trim()||null};if(!editing){packet.parent_id=creatingParent?.id||null;packet.drive=$('project-drive').value;}const bytes=s=>new TextEncoder().encode(s).length;if(!packet.name.trim()||bytes(packet.name)>200||/[\/\\\x00-\x1f\x7f]/.test(packet.name)||['.','..'].includes(packet.name)){$('form-error').textContent='Use a name of up to 200 UTF-8 bytes without slashes or control characters.';return;}if(bytes(packet.description)>4000){$('form-error').textContent='Description must be at most 4000 UTF-8 bytes.';return;}busy=true;lock();try{const p=await api(editing?'/projects/'+editing.id:'/projects',{method:editing?'PATCH':'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(packet)});$('editor').close();history.replaceState(null,'','#'+p.id);show(p);busy=false;await load();}catch(e){$('form-error').textContent='Could not save: '+e.message+'. If the connection failed, refresh before retrying creation.';}finally{busy=false;lock();}};
$('delete').onclick=()=>{if(busy||loading||!selected)return;deleting=selected;$('delete-title').textContent='Delete '+deleting.name+'?';$('delete-note').textContent='This deletes the project and all of its subprojects. Choose what happens to '+deleting.directory+' and all nested files. This affects all devices.';document.querySelector('input[value=keep]').checked=true;$('delete-error').textContent='';$('deletion').showModal();};
$('delete-form').onsubmit=async e=>{e.preventDefault();if(busy)return;busy=true;lock();try{await api('/projects/'+deleting.id,{method:'DELETE',headers:{'Content-Type':'application/json'},body:JSON.stringify({destroy_directory:document.querySelector('input[name=retention]:checked').value==='destroy'})});$('deletion').close();history.replaceState(null,'',location.pathname);show(null);busy=false;await load();}catch(e){$('delete-error').textContent='Deletion could not be confirmed: '+e.message+'. Close this dialog and refresh to check the project. Interrupted file cleanup completes on server restart.';}finally{busy=false;lock();}};
$('add-child').onclick=()=>{if(selected)openEditor(null,selected);};$('create').onclick=()=>openEditor(null);$('edit').onclick=()=>openEditor(selected);$('refresh').onclick=()=>load();$('more').onclick=()=>load(true);$('search').oninput=render;$('project-name').oninput=directoryNote;$('project-drive').onchange=directoryNote;
for(const [dialog,button] of [['editor','cancel'],['deletion','delete-cancel']]){$(button).onclick=()=>{if(!busy)$(dialog).close();};$(dialog).addEventListener('cancel',e=>{if(busy)e.preventDefault();});}
let boardData=null,boardProject=null,boardRevision=0,boardLoading=false,boardEditing=null;
function boardMessage(text,error=false){$('board-status').textContent=text;$('board-status').classList.toggle('error',error);}
function boardBase(){return '/projects/'+boardProject+'/boards';}
function boardButton(parent,label,action,danger=false){const b=document.createElement('button');b.textContent=label;b.dataset.sparkPermission='boards.write';if(danger)b.className='danger';b.onclick=action;parent.append(b);return b;}
function renderBoard(){
 $('board-columns').replaceChildren();for(const id of ['board-rename','board-delete','column-new'])$(id).hidden=!boardData;
 if(!boardData)return;
 for(const column of boardData.columns){const lane=document.createElement('section');lane.className='kanban-column';const title=document.createElement('h3');title.textContent=column.name+' ('+column.tasks.length+')';lane.append(title);const actions=document.createElement('div');actions.className='actions';lane.append(actions);boardButton(actions,'Rename',()=>boardEdit('column-edit',column));boardButton(actions,'Delete',()=>boardEdit('column-delete',column),true);boardButton(actions,'Add task',()=>boardEdit('task-new',column));
 for(const task of column.tasks){const card=document.createElement('article');card.className='task-card';const name=document.createElement('h4');name.textContent=task.name;card.append(name);const severity=document.createElement('p');severity.textContent='Severity: '+task.severity;card.append(severity);const description=document.createElement('p');description.textContent=task.description;card.append(description);const actions=document.createElement('div');actions.className='actions';card.append(actions);boardButton(actions,'Edit / move',()=>boardEdit('task-edit',task));boardButton(actions,'Delete',()=>boardEdit('task-delete',task),true);lane.append(card);}
 $('board-columns').append(lane);}
 if(!boardData.columns.length)boardMessage('This board has no columns. Add a column to start organising tasks.');lock();
}
async function loadBoards(project,preferred){const token=++boardRevision;const old=project===boardProject?boardData?.id:null;boardProject=project;boardLoading=true;lock();boardMessage('Loading boards…');try{const page=await api('/projects/'+project+'/boards');const choice=[preferred,old,page.boards[0]?.id].find(id=>page.boards.some(b=>b.id===id));const data=choice?await api('/projects/'+project+'/boards/'+choice):null;if(token!==boardRevision||selected?.id!==project)return;boardData=data;$('board-picker').replaceChildren();for(const board of page.boards){const option=document.createElement('option');option.value=board.id;option.textContent=board.name;$('board-picker').append(option);}if(choice)$('board-picker').value=choice;boardMessage(data?'':'No boards yet. Create a board for this project.');renderBoard();}catch(e){if(token===boardRevision){boardData=null;renderBoard();boardMessage('Could not load boards: '+e.message+'. Refresh boards to retry.',true);}}finally{if(token===boardRevision){boardLoading=false;lock();}}}
function boardEdit(kind,item){if(busy||loading||boardLoading)return;boardEditing={kind,item,project:boardProject,board:boardData?.id};const remove=kind.endsWith('delete'),task=kind.startsWith('task');$('board-form-title').textContent=({'board-new':'New board','board-edit':'Rename board','board-delete':'Delete board?','column-new':'New column','column-edit':'Rename column','column-delete':'Delete column?','task-new':'New task','task-edit':'Edit or move task','task-delete':'Delete task?'})[kind];$('board-form-note').textContent=kind==='board-delete'?'This permanently deletes '+boardData.name+' and all its columns and tasks.':kind==='column-delete'?'Delete '+item.name+'? Move or delete its tasks first.':kind==='task-delete'?'Permanently delete '+item.name+'?':'';$('board-name-field').hidden=remove;$('board-name').required=!remove;$('board-name').value=kind.endsWith('edit')?item.name:'';$('board-severity-field').hidden=!task||remove;$('board-severity').value=kind==='task-edit'?item.severity:'Normal';$('board-description-field').hidden=!task||remove;$('board-description').value=kind==='task-edit'?item.description:'';$('board-destination-field').hidden=kind!=='task-edit';$('board-destination').replaceChildren();if(kind==='task-edit')for(const c of boardData.columns){const option=document.createElement('option');option.value=c.id;option.textContent=c.name;$('board-destination').append(option);}$('board-destination').value=kind==='task-edit'?item.column_id:'';$('board-error').textContent='';$('board-save').textContent=remove?'Delete permanently':'Save';$('board-editor').showModal();}
$('board-form').onsubmit=async event=>{event.preventDefault();if(busy)return;const {kind,item,project,board}=boardEditing;const remove=kind.endsWith('delete');const base='/projects/'+project+'/boards';let path=base,method='POST',packet={name:$('board-name').value};if(!remove&&(!packet.name.trim()||new TextEncoder().encode(packet.name).length>200)){$('board-error').textContent='Use a nonblank name of up to 200 UTF-8 bytes.';return;}
 if(kind==='board-edit'||kind==='board-delete'){path+='/'+board;method=remove?'DELETE':'PATCH';}
 if(kind==='column-new')path+='/'+board+'/columns';
 if(kind==='column-edit'||kind==='column-delete'){path+='/'+board+'/columns/'+item.id;method=remove?'DELETE':'PATCH';}
 if(kind==='task-new'||kind==='task-edit'){packet.severity=$('board-severity').value;packet.description=$('board-description').value;if(new TextEncoder().encode(packet.description).length>4000){$('board-error').textContent='Description must be at most 4000 UTF-8 bytes.';return;}if(kind==='task-new')path+='/'+board+'/columns/'+item.id+'/tasks';else{path+='/'+board+'/tasks/'+item.id;method='PATCH';packet.column_id=$('board-destination').value;}}
 if(kind==='task-delete'){path+='/'+board+'/tasks/'+item.id;method='DELETE';}
 busy=true;lock();try{const result=await api(path,{method,...(remove?{}:{headers:{'Content-Type':'application/json'},body:JSON.stringify(packet)})});$('board-editor').close();await loadBoards(project,kind==='board-new'?result.id:board);}catch(e){$('board-error').textContent=e.message==='column not empty'?'Move or delete every task before deleting this column.':'Could not save: '+e.message+'. If the connection failed, close and refresh before retrying.';}finally{busy=false;lock();}};
$('board-new').onclick=()=>boardEdit('board-new');$('board-rename').onclick=()=>boardEdit('board-edit',boardData);$('board-delete').onclick=()=>boardEdit('board-delete',boardData);$('column-new').onclick=()=>boardEdit('column-new');$('board-refresh').onclick=()=>{if(selected)loadBoards(selected.id);};$('board-picker').onchange=()=>{if(selected)loadBoards(selected.id,$('board-picker').value);};$('board-cancel').onclick=()=>{if(!busy)$('board-editor').close();};$('board-editor').addEventListener('cancel',e=>{if(busy)e.preventDefault();});
let transferBusy=false,transferJob=null;
const transferPermission='projects.read projects.write boards.read boards.write files.read files.write';
function transferMessage(text,error=false){$('transfer-status').textContent=text;$('transfer-status').classList.toggle('error',error);}
function transferLock(value){transferBusy=value;$('import-project').disabled=value;$('export-project').disabled=value;$('import-prepare').disabled=value;$('import-cancel').disabled=value;$('review-apply').disabled=value;$('review-cancel').disabled=value;}
async function pollTransfer(job){sessionStorage.setItem('spark-project-transfer',job.id);while(job.state==='preparing'||job.state==='applying'){transferMessage((job.kind==='export'?'Exporting project':'Preparing import')+' · '+(job.processed_bytes/1048576).toFixed(1)+' MiB processed');await new Promise(r=>setTimeout(r,800));job=await api('/projects/transfers/'+job.id);}if(job.state==='failed'){await api('/projects/transfers/'+job.id,{method:'DELETE'});sessionStorage.removeItem('spark-project-transfer');throw new Error(job.error||'Transfer failed');}return job;}
function exported(job){api('/projects/transfers/'+job.id,{method:'DELETE'}).catch(()=>{});$('transfer-download').hidden=false;$('transfer-download').href=job.result.file.download_url;$('transfer-download').textContent='Download '+job.result.file.name;transferMessage('Export saved in Files → persistent drive → /project-exports.');sessionStorage.removeItem('spark-project-transfer');}
$('export-project').onclick=async()=>{if(transferBusy||!selected)return;transferLock(true);$('transfer-download').hidden=true;try{let job=await api('/projects/'+selected.id+'/export',{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'});exported(await pollTransfer(job));}catch(e){transferMessage(e.message+'. A transfer already started can be resumed by refreshing this page.',true);}finally{transferLock(false);}};
$('import-project').onclick=async()=>{if(transferBusy)return;try{const drives=(await api('/files/drives')).drives;$('import-drive').replaceChildren();for(const d of drives)if(d.online)$('import-drive').add(new Option(d.letter+': '+(d.persistent?'Server storage':d.path),d.letter));$('import-target').replaceChildren(new Option('Detect by project ID or name',''));if(selected)$('import-target').add(new Option('Import into '+selected.name,selected.id));$('import-upload').value='';$('import-error').textContent='';$('import-dialog').showModal();}catch(e){transferMessage(e.message,true);}};
$('import-target').onchange=()=>{if($('import-target').value&&selected)$('import-drive').value=selected.drive_letter;};
$('import-cancel').onclick=()=>{if(!transferBusy)$('import-dialog').close();};
$('import-form').onsubmit=async e=>{e.preventDefault();if(transferBusy)return;const file=$('import-upload').files[0];if(!file)return;transferLock(true);try{transferMessage('Uploading archive…');const upload=await api('/files?'+new URLSearchParams({name:file.name,directory:'/project-imports',drive:$('import-drive').value}),{method:'POST',headers:{'Content-Type':'application/octet-stream'},body:file});const packet={file_id:upload.id,drive:$('import-drive').value};if($('import-target').value)packet.target_project_id=$('import-target').value;const job=await api('/projects/imports',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(packet)});$('import-dialog').close();showReview(await pollTransfer(job));}catch(e){$('import-error').textContent=e.message;transferMessage(e.message,true);}finally{transferLock(false);}};
function showReview(job){transferJob=job;$('review-entries').replaceChildren();$('review-error').textContent='';$('review-summary').textContent=job.entries.length+' items · '+job.result.drive+':'+job.result.directory+'. Existing items default to Keep; new items default to Import. Discard skips the incoming item and its descendants. Local-only items are retained.';for(const entry of job.entries){const row=document.createElement('section');row.className='transfer-entry';row.dataset.key=entry.key;const title=document.createElement('h3');title.textContent=entry.kind+' · '+entry.label+(entry.conflict?' · Conflict':entry.exists?' · Already present':' · New');row.append(title);const detail=document.createElement('details'),summary=document.createElement('summary');summary.textContent='Compare details';detail.append(summary);const values=document.createElement('pre');values.textContent='Local\n'+JSON.stringify(entry.local,null,2)+'\nIncoming\n'+JSON.stringify(entry.incoming,null,2);detail.append(values);row.append(detail);const select=document.createElement('select');select.setAttribute('aria-label','Action for '+entry.label);select.add(new Option(entry.exists?'Keep local':'Skip new item','keep'));select.add(new Option(entry.exists?'Replace with incoming':'Import incoming','import'));select.add(new Option('Discard incoming branch','discard'));if(entry.mergeable)select.add(new Option('Merge text…','merge'));select.value=entry.default_action;row.append(select);const editor=document.createElement('div');editor.className='merge-editor';row.append(editor);select.onchange=async()=>{editor.hidden=select.value!=='merge';if(select.value!=='merge'||editor.childElementCount)return;select.disabled=true;try{const content=await api('/projects/transfers/'+job.id+'?text='+encodeURIComponent(entry.key));const sources=document.createElement('div');sources.className='merge-sources';for(const [name,text]of [['Local',content.local],['Incoming',content.incoming]]){const label=document.createElement('label');label.textContent=name;const area=document.createElement('textarea');area.readOnly=true;area.value=text;label.append(area);sources.append(label);}editor.append(sources);const label=document.createElement('label');label.textContent='Merged result — edit the final text to keep';const output=document.createElement('textarea');output.className='merged-result';output.value=content.local;label.append(output);editor.append(label);}catch(e){select.value='keep';$('review-error').textContent=e.message;}finally{select.disabled=false;}};$('review-entries').append(row);}transferMessage('Import ready for review. Nothing has been changed.');$('review-dialog').showModal();}
$('review-cancel').onclick=async()=>{if(transferBusy)return;try{await api('/projects/transfers/'+transferJob.id,{method:'DELETE'});$('review-dialog').close();sessionStorage.removeItem('spark-project-transfer');transferMessage('Import discarded. The uploaded ZIP remains in /project-imports.');}catch(e){$('review-error').textContent=e.message;}};
$('review-apply').onclick=async()=>{if(transferBusy||!transferJob)return;const resolutions={};for(const row of $('review-entries').children){const action=row.querySelector('select').value;const resolution={action};if(action==='merge'){const editor=row.querySelector('.merged-result');if(!editor){$('review-error').textContent='Wait for text previews to finish loading.';return;}resolution.content=editor.value;}resolutions[row.dataset.key]=resolution;}transferLock(true);for(const control of $('review-entries').querySelectorAll('select,textarea'))control.disabled=true;transferMessage('Applying reviewed changes…');try{const job=await api('/projects/transfers/'+transferJob.id+'/apply',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({resolutions})});$('review-dialog').close();await api('/projects/transfers/'+job.id,{method:'DELETE'});sessionStorage.removeItem('spark-project-transfer');history.replaceState(null,'',job.result.project_id?'#'+job.result.project_id:location.pathname);await load();transferMessage('Import complete. '+job.result.applied_items+' items applied. Uploaded ZIP retained in /project-imports.');}catch(e){$('review-error').textContent=e.message+'. Start a fresh import review before retrying.';transferMessage(e.message,true);}finally{transferLock(false);}};
for(const id of ['import-dialog','review-dialog'])$(id).addEventListener('cancel',e=>{e.preventDefault();if(!transferBusy)$(id==='import-dialog'?'import-cancel':'review-cancel').click();});
(async()=>{const id=sessionStorage.getItem('spark-project-transfer');if(!id)return;transferLock(true);try{const job=await pollTransfer(await api('/projects/transfers/'+id));if(job.state==='review')showReview(job);else if(job.kind==='export')exported(job);else{transferMessage('Import completed.');sessionStorage.removeItem('spark-project-transfer');}}catch(e){transferMessage(e.message,true);sessionStorage.removeItem('spark-project-transfer');}finally{transferLock(false);}})();

window.addEventListener('hashchange',()=>{if(!busy)select();});load();
</script></body></html>)HTML";
